                values: new object[,]
                {
                    { 105, "إبراهيم عيسى", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رواية جريئة توضح كيف يساء استخدام الدين\nمن أكثر الكتب مبيعًا\nالقائمة القصيرة للجائزة العالمية للرواية العربية 2013\nتحولت إلى فيلم سينمائي ناجح\nمديح\n«من الوجهة الفنية والفكرية، رواية الموسم الإبداعي... شهادة دامغة على العصر» المصري اليوم\n«عمل ملحمي، في مصاف «قصة مدينتين» للإنجليزي «تشارلز ديكنز»، أو «الحرب والسلام» للروسي «تولستوي»، أو رائعة «باسترناك»، «دكتور زيفاجو»... كما أنها استمرار موفق لمدرسة الروائي العظيم، وأمير الرواية العربية، نجيب محفوظ... إنها تحكي تراجيديا مصر المُباركية بتكثيف مُنقطع النظير فى دقته الاجتماعية وتشويقه الروائي. لذلك تستحق جائزة الدولة فى الأدب... فهل هناك من يسمعون أو من يقرأون!؟» الوطن\n«كتاب يأخذك إلى عالم سفلي ترى منه الدنيا على شاشة التلفزيون وما وراءها من أسرار... سخرية حادة على طول. لا ترحم أحدًا» الجمهورية أونلاين\n«تنقل القارئ إلى تفاصيل وعلاقات مثيرة ومدهشة وتنكشف في النهاية عن مفاجآت ووقائع تدخل في دائرة المسكوت عنه وتقتحم الخطوط الحمراء في دهاليز الفساد السياسي والسلطة المستبدة» عُمان\n«يشرِّح إبراهيم عيسى بجرأة شديدة ظواهر بالجملة في المجتمع، يدخل إلى حقول ألغام، و«أعشاش دبابير» قد لا يرضى عنها البعض، وينتقد بواقعية مفرطة ما حدث، وما زال يحدث... يعمد إلى سهام السخرية وخفة الدم، حتى في أحلك اللحظات، وأشدها عتمة» الإمارات اليوم\n««مولانا» التلفزيوني بطل زماننا» الحياة", "/images/products/9789778507805.webp", "9789778507805", "مولانا", 584, 300m, new DateTime(2014, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 106, "إبراهيم عيسى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يعود إبراهيم عيسى بعد أربع سنوات من صدور «مولانا» (القائمة القصيرة للجائزة العالمية للرواية العربية – البوكر 2013) ليتناول المسكوت عنه في تاريخنا الإسلامي. ففي سرد مبهر وأحداث مشوقة إلى أقصى درجة يربط ببراعة بين صراعات المسلمين الأوائل بعد وفاة الرسول وفتح مصر واغتيال عثمان بن عفان وعلي بن أبي طالب. إن إبراهيم عيسى يخلق لنا – ولأول مرة – صورة أقرب ما تكون للحقيقة عن هذه السنوات المهمة والتي غيرت وجه العالم للأبد.\nسيُذهل القارئ عندما يعرف أن جميع شخصيات هذه الرواية حقيقية، وأن كل أحداثها تستند على وقائع وردت في المراجع التاريخية المعتمدة. وهي الجزء الأول من سلسلة «القتلة الأوائل».", "/images/products/9789776467569.webp", "9789776467569", "رحلة الدم: ثلاثية القتلة الأوائل ج1", 712, 375m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 107, "إبراهيم عيسى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "المؤلف من أكثر الكتاب مبيعًا\nالجزء الأول من السلسلة الروائية من أكثر الكتب مبيعًا\nرحلة الدم لم تنتهِ إذن.\nبل إن الدم أكثر وأغزر.\nلم تكن أبدًا فتنة، بل أعمق وأخطر.\nانسَ كل ما كنت تعرفه عن الفتنة الكبرى، فأنت تدنو من الحقيقة الآن في سردٍ أقرب إلى الواقع وأكثر تشويقًا مع هذه الرواية التي يستكمل بها إبراهيم عيسى مسيرة «القتلة الأوائل»، والتي بدأها في «رحلة الدم» (جائزة نجيب محفوظ في الرواية 2018)، ليتناول السنوات اللغز في تاريخنا الإسلامي.\nونؤكد للقارئ مرَّة أخرى أن جميع شخصيات هذه الرواية المبهرة حقيقية، وأن كل أحداثها تستند إلى وقائع وردت في المراجع التاريخية المعتمدة.", "/images/products/9789776467996.webp", "9789776467996", "حروب الرحماء: ثلاثية القتلة الأوائل ج2", 688, 450m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 108, "إبراهيم عيسى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "المؤلف من أكثر الكتاب مبيعًا\nالجزءان الأوليان من أكثر الكتب مبيعًا\n«سيوف الآخرة» هي الرواية التي تصل بك إلى المحطة الأخيرة، أو التي تظنها كذلك في «رحلة الدم». يكمل إبراهيم عيسى هنا دائرة «القتلة الأوائل» منذ اللحظة التي قتل فيها عثمان بن عفان حتى مقتل علي بن أبي طالب. العديد من الألغاز التي تكونت وتراكمت في كتب التاريخ تفكها هذه الرواية، تكشفها وتعريها من غموضها ومن كذبها وربما من تلفيقها. والكثير من الثقوب السوداء التي هوت فيها الحقيقة، وردمت فوقها أضاليل الركام تنفضها «سيوف الآخرة»، تنقب عنها وتعثر عليها، حيث تزيح الأوهام والأكاذيب والتخيلات والتوهمات والدعايات من عقل القارئ ليرى مفاجأة وصدمة ودهشة لقائه بالحقيقة كأنه يراها أو يعيشها، أو كأنه عاش أخيرًا كي يراها.\nلعل أهم ما ستضمنه لك قراءة «سيوف الآخرة»، مع التشويق والإثارة وسرعة نبضات القلب وارتفاع طفيف في ضغط الدم، أنك تستحق أن تعرف لماذا تسمع وترى الآن، وبعد مئات السنوات من أحداث «سيوف الآخرة»، دوي الرصاص، وانفجار الدم، وتفجر الكراهية، وبؤس الفتن اليومية، والجميع الذين قلوبهم شتى.\nاقرأها لتكون شاهدًا على الجريمة لو استدعاك المستقبل للإدلاء بشهادتك...\n*\nوصلت رواية «رحلة الدم» (الجزء الأول من ثلاثية القتلة الأوائل) إلى القائمة الطويلة لجائزة الشيخ زايد للكتاب - فرع الآداب عام 2017، ثم فازت بجائزة نجيب محفوظ للرواية عام 2018. ووصلت أيضًا رواية «حروب الرحماء» (الجزء الثاني من الثلاثية) إلى القائمة الطويلة لجائزة الشيخ زايد للكتاب - فرع الآداب عام 2019. وحققتا نجاحًا جماهيريًّا ونقديًّا كبيرًا، وبيعت منهما عشرات الآلاف من النسخ حتى الآن.", "/images/products/9789779603247.webp", "9789779603247", "سيوف الآخرة: ثلاثية القتلة الأوائل ج3", 640, 375m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 109, "لطيفة الزيات", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "واحدة من أهم الروايات العربية\nنافدة منذ فترة طويلة ومطلوبة من محبي الأدب\nحوَّلها المخرج هنري بركات إلى فيلم ناجح من بطولة فاتن حمامة وصالح سليم، فاز بجائزتي أفضل فيلم وأفضل ممثلة لفاتن حمامة في مهرجان جاكرتا السينمائي\nليلى فتاة ذكية، ومليئة بالحيوية، تعيش في مجتمع تقليدي لا ينتظر من المرأة إلا الخنوع والطاعة. ولكن ليلى غير مستعدة للتسليم بسهولة، فتناضل من أجل أن تحصل على حريتها كإنسانة، كما تنخرط في الحركة الوطنية من أجل أن تحرر بلادها أيضًا. وبينما تغلي مصر وتثور خلال أربعينيات وخمسينيات القرن العشرين فتواجه العثرات والانتصارات، نعيش مع ليلى آمالها وانهزاماتها وانتصاراتها في حياتها الشخصية في سبيل حب صادق تصبو إليه، فهل ستجد في نفسها القوة لتفتح الباب وتنطلق؟\nرواية رائعة تتحرك ببراعة مذهلة بين الحميمي والعام، بين سيرة الفرد وتاريخ الوطن.\nمديح\n«رواية «الباب المفتوح» علامة فارقة في كتابة المرأة العربية.. لطيفة الزيات كاتبة أصيلة.. لم تصور المسعى إلى الحرية كطريق سهل وواضح، بل جسدته بعثراته وصعوباته ومزالقه، وأيضًا ببهائه وسكينته. كتبت «الباب المفتوح» في كل نصوصها ففتحت الباب لأجيال من الكاتبات ينتسبن إليها ويواصلن الطريق» رضوى عاشور", "/images/products/9789776467286.webp", "9789776467286", "الباب المفتوح", 464, 180m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 110, "خيري شلبي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "«لصاحبي تاريخ ذو وجهين، تستطيع أن تختار أيهما لتسبح فيه إلى ما لا نهاية: إن اخترت وجه السوابق وجدت ألف سابقة وسابقة دونتها محاضر البوليس، ووقف بشأنها أمام النيابات والمحاكم، واستأنف فيها واستؤنفت فيه. أما ما لم تدونه المحاضر فحدِّث ولا حرج. وإن اخترت وجه العز وجدت ما لا يصدَّق، فقد جاء حين من الدهر كان صاحبي يمتلك هذا الشارع بأكمله، وهو أهم شارع في المنطقة، إذ تتمركز فيه تجارات لا حصر لها، ويتدفق في هذا الشارع وحده من الأموال ورؤوس الأموال ما يصلح أن يقيم دولة عظيمة، لكن الذين يملكونه أوباش لا يهمهم سوى المكسب فحسب!\n«اللي جه بلاش يروح بلاش»، هكذا يقول المثل الشعبي على لسان صاحبي»\nمديح\n«عندما عرف جيلنا فضل خيري شلبي وضعناه على القمة» - إبراهيم عبد المجيد\n«خيري شلبي أحد الروافد العظيمة في فن الرواية... أسطورة حقيقية» - إبراهيم داود", "/images/products/9789776743953.webp", "9789776743953", "الشطار", 624, 250m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 111, "خيري شلبي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رحلات الطرشجي الحلوجي تحتوي على أحداث مدهشة غريبة، وخواطر مسلية وعجيبة، وأخبار مذهلة ووقائع مؤسفة رهيبة، تتحدث عن حياة الأوائل والأواخر، والأماجد والأسافل.\nخطها يراع العبد الفقير إلى ربه تعالى، العالم غير العلَّامة، والحبر غير الفهَّامة، ابن شلبي الحنفي المصري الطرشجي الحلوجي، كفانا الله شر جهله، آمين!\nمديح\n«خيري شلبي أمير الروائيين الصعاليك» - نجيب محفوظ\n«خيري شلبي تجربة إنسانية وإبداعية فريدة» - جابر عصفور", "/images/products/9789776743946.webp", "9789776743946", "رحلات الطرشجي الحلوجي", 464, 200m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 112, "نائل الطوخي", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر الروايات مبيعًا وترجمت للإنجليزية والفرنسية\n«القصة بدأت منذ وقت طويل، امتدت لأكثر من جيل، وحلَّقت فوق أكثر من مكان، من جنوب مصر إلى شمالها، واحتوت على الكثير من المواعظ والدروس الأخلاقية، والكثير من الفلسفة العميقة بخصوص الإنسان ورغباته وصفاته. القصة هي واحدة من تلك القصص النادرة في تاريخ الإنسانية، التي تربط المتعة بالتشويق بالمعلومة المفيدة والنصائح الغالية...».\nمديح\n«أول ما قرأت «نساء الكرنتينا» جفلت، فما أمامي لم يكن رواية كما أعرف الرواية، ولا أسلوبها كان أسلوب رواية. كان الطوخي يضرب بالأدب عرض الحائط» - عباس بيضون، «السفير»\n«بنفس ملحمي يتهكم من كل شيء، وخفة روح غير عادية، والتعامل بطزاجة مدهشة مع موتيفات قديمة كالعنف أو توالي الأجيال، استطاع نائل أن يبدع عملًا غير مسبوق في تاريخ الرواية العربية، بلغة شديدة الخصوصية ترقص ما بين الفصحى البسيطة والعامية المصرية الأشد سخونة وربما فُحشًا» - محمد عبد النبي\n«عمل مثير وأصيل يمثِّل مساهمة مهمة في الأدب المصري والعربي المعاصر» - «بانيبال»\n«رواية ساخرة بشدة» - «النيويورك تايمز»\n«رواية تشدك» - أنديل، «مدى مصر»\n«نائل الطوخي روائي مخيف... رواية لامعة» - «لو موند»\n«المجرمون هنا أبطال، وأفراد العصابات قديسون» - «شيكاجو تريبيون»", "/images/products/9789778648034.webp", "9789778648034", "نساء الكرنتينا", 416, 300m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 113, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتب د. أحمد خالد توفيق من الأكثر مبيعًا\n\n«دعني أنتحِ بك جانبًا لأخبرك بسر لا يعرفه سوانا. احترس! لا ترفع صوتك.. عندما نحلم، فإن وعينا يسافر لبعد آخر ليمارس حياة أخرى ويلقى أناسًا آخرين، ويعرف وجوهًا أخرى. «فرويد» لم يقل هذا، لكن دعني أخبرك أنها الحقيقة. بل هي الحقيقة الوحيدة...»\n\nوقال الله: «فليكن نور» فكان نور.\n\nكتب د. أحمد خالد توفيق من قبل عن عالم كابوسي، يمتزج فيه معنى الظلام بمعاني الجهل والقهر والتخبط. ولكنه اليوم يقدم لنا رواية ديستوبية مثيرة عن عالم لم يعد النور فيه من حقوق الإنسان الطبي", "/images/products/9789776467552.webp", "9789776467552", "في ممر الفئران", 384, 250m, new DateTime(2016, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 114, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتب د. أحمد خالد توفيق من الأكثر مبيعًا\nآخر ما كتب للدكتور أحمد خالد توفيق\n«الآن أنت تعرف القصة يا سامي، وتعرف لماذا اصطحبتك إلى المقبرة ليلًا،\nوتعرف لماذا أنت مقيد ومكمم الفم بجوارها الآن!\nلقد انتهت قصتي، وحان وقت العمل!\nلا تحاول الصراخ، فلن يسمعك أحد!\nسأحاول أن تمر اللحظات القادمة بسرعة!!»\n*&lt;w:t&gt;*&lt;w:t&gt;*\nيحتوي هذا الكتاب 11 قصة مليئة بالتشويق والرعب والإثارة، وهي آخر قصص تركها لنا د. أحمد خالد توفيق.", "/images/products/karma-1-mw128b58.webp", null, "رفقاء الليل", 320, 150m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 115, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "كتب د. أحمد خالد توفيق من الأكثر مبيعًا\nآخر كتاب للدكتور أحمد خالد توفيق\n«سأعترف لك بشيء مخيف.. كل ما أقوله هنا سيظل سرًّا.. أليس كذلك؟ في البدء بدأ القط يتوتر ويعوي.. يطلب الزواج.. كانت تحبه لأنه قطها، لكنه أثار أعصابها، وفي يوم خدرته و... واستأصلت رجولته!».\nآخر باقة مُنتقاة من الوحوش، ومصاصي الدماء، والسَّفاحين، وآكلي لحوم البشر، والموتى الأحياء، والكائنات الفضائية، دفع بها د. أحمد خالد توفيق إلى النشر. ندعوك لقراءتها وقضاء ساعات من المتعة الصافية.", "/images/products/karma-2-mw128bdp.webp", null, "أفراح المقبرة", 240, 120m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 116, "أحمد خالد توفيق", 9, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "سوف نفتح هذه المجموعة القصصية ونحن مفعمون بالأسئلة، ونتركها مفعمين بالخوف: ما مهنة ذلك الرجل الغامض في تلك المسابقة التلفزيونية؟ الموقع الغامض الذي يعرض على الناس منظر جثتك الممزقة. شارع المشاط الهادئ المسالم الذي يكتم سكانه سرًّا مرعبًا. العلاج الشنيع الذي يقدمه الطبيب الأرمني والذي يعيد لك الحواس وربما الأطراف المبتورة. «زوزانكا» تحاول معرفة ما يوجد في قبو أسرة زوجها. الكائن القادم من جانب النجوم لينشر الهول في الأرض. إنها رحلة طويلة مرهقة عبر سراديب الرعب وأقبيته، بينما صراخ الموتى يصم أذنيك.", "/images/products/9789776467064.webp", "9789776467064", "الهول", 248, 130m, new DateTime(2014, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 117, "أحمد خالد توفيق", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "اشتهرت قديمًا «شَربة الحاج داود اللي بتطرُد الدود» كعلاج سحري يداوي كل شيء تقريبًا، من الديدان حتى الأورام الخبيثة والعقم والصداع.\nهذه النوعية من العلاجات السحرية توجد في كل الحضارات تقريبًا... كما توجد أيضًا مضادات حيوية، وأدوية مناعة، ولقاحات، أفنى عديد من العلماء المحترمين أعمارهم كي يهدوها لنا.\nيأخذنا الدكتور أحمد خالد توفيق في كتابه الجديد في رحلة ممتعة ومثيرة، يتناول فيها العلم وشبه العلم ونصف العلم واللاعلم.\nبعضه انبهار بالعلم، وبعضه دهشة من كراهيتنا له وحساسيتنا المفرطة نحوه، وبعضه محاولة لفضح أساليب النصب في الطب وسواه...\nكتاب يدفعك للتفكير والنظر للدنيا بشكل مختلف.", "/images/products/9789776467200.webp", "9789776467200", "شربة الحاج داود", 240, 100m, new DateTime(2015, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 118, "توماس هاريس", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "باعت الرواية أكثر من 10 ملايين نسخة\nمن أفضل كتب التشويق والجريمة\nقاتل متسلسل، معروف فقط باسم مستعار غريب (بافالو بيل)، يطارد نساء معينات. لديه هدف، ولكن لا أحد يستطيع فهمه، لأن الجثث تُكتشف في حالات مختلفة. كلاريس متدربة شابة في أكاديمية مكتب التحقيقات الفدرالي، تُفاجأ باستدعاء من مديرها. مهمتها إجراء مقابلة مع الدكتور هانيبال لِكتر، الطبيب النفسي اللامع والقاتل المروع، المحبوس الآن تحت المراقبة الدقيقة في مستشفى للمجرمين المجانين. هل تستطيع خبرة لِكتر مع القتلة أن تساعده في تعقب بافالو بيل والقبض عليه؟\nتضطرب كلاريس عندما تجد نفسها في علاقة غريبة ومكثفة مع لِكتر شديد الملاحظة. أدلته المبهمة - عن بافالو بيل وعنها - تطلق كلاريس في بحث سيجده القارئ مذهلًا ومروعًا ومقنعًا تمامًا.\nتحوَّلت هذه الرواية الأكثر مبيعًا والفائزة بعدة جوائز مهمة إلى فيلم سينمائي شهير فاز بجائزة الأوسكار من بطولة جودي فوستر وأنتوني هوبكنز.\nمديح\n«رواية ممتعة إلى أقصى درجة. حبكة جميلة، مكتوبة ببراعة. روايات الإثارة لا تأتي أفضل من هذا» - كلايف باركر\n«نموذج مثالي لكيفية كتابة رواية تشويق. تحفة فنية من التوتر المطلق الذي ينطلق بسلاسة نحو ذروته... هاريس - بكل بساطة - أفضل روائي تشويق يكتب اليوم» - الواشنطن بوست\n«قصة نفسية مثيرة منسوجة ببراعة» - الأسوشيتد برس\n«رائعة» - النيويورك تايمز\n«ذات وتيرة سريعة... مثيرة للغاية» - شيكاغو تريبيون", "/images/products/9789779603049.webp", "9789779603049", "صمت الحملان", 440, 300m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 119, "دافني دو مورييه", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "باعت أكثر من 3 ملايين نسخة\nأول ترجمة عربية\nفي مونت كارلو، تلتقي بطلتنا الشابة التي تعمل مرافقة لسيدة ثرية بالأرمل المحطم ماكسيم دي وينتر، فيسحرها بشخصيته وثرائه، ويعرض عليها الزواج. ولكن عندما يصلان إلى قصره الريفي المنعزل في بريطانيا، تجد ماكس يتحول إلى رجل مختلف، وتجد شبح ذكرى زوجته المتوفاة ريبيكا يسيطر على كل زاوية وكل غرفة، بل على حياتها بأكملها، وتشعر برعب يجثم عليها رويدًا رويدًا ويهدد زواجهما... فهل ستستسلم؟\nإنها قصة مثيرة عن شابة تدافع عن حبها، وتصارع من أجل العثور على هويتها.\nلا تزال هذه الرواية الشهيرة واحدة من أكثر الكتب مبيعًا، ولا تزال تُطبع باستمرار منذ نشرها عام 1938، وقد فازت بجائزة أنتوني لأفضل رواية في القرن العشرين، وما زالت تُقتبس دوريًّا للتلفزيون والراديو والمسرح والسينما، ومنها فيلم ألفريد هيتشكوك الشهير الذي فاز بجائزة الأوسكار.\nمديح\n«ممتازة» - ستيفن كينج\n«واحدة من أكثر الروايات تأثيرًا في القرن العشرين» - سارة واترز", "/images/products/9789779603179.webp", "9789779603179", "ريبيكا", 576, 450m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 120, "تشاك بولانيك", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر الكتب مبيعًا\n\nترجمة رائعة لكاتبنا الكبير د. أحمد خالد توفيق\n\nتحتوي هذه الطبعة على خاتمة جديدة للمؤلف تُنشر لأول مرة باللغة العربية\n\nالقاعدة الأولى لنادي القتال: لا تتكلم عن نادي القتال.\n\nالقاعدة الثانية لنادي القتال: لا تتكلم عن نادي القتال.\n\nالقاعدة الثالثة لنادي القتال: إن صرخ أحدهم أو عجز عن الدفاع عن نفسه، ينتهي القتال.\n\nالقاعدة الرابعة لنادي القتال: رجلان فقط لكل معركة.\n\nالقاعدة الخامسة لنادي القتال: معركة واحدة في كل مرة.\n\nالقاعدة السادسة لنادي القتال: لا قمصان، لا أحذية.\n\nالقاعدة", "/images/products/9789778648027.webp", "9789778648027", "نادي القتال", 272, 240m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 121, "هرمان هسه", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "ربما تكون رواية هسه الشهيرة والمؤثرة أهم حكاية رمزية أنتجها عصرنا المضطرب، دمج فيها هسه التقاليد الروحية الشرقية والغربية مع التحليل النفسي والفلسفة. هذه الحكاية البسيطة والغريبة، المكتوبة بتعاطف عميق مع الإنسانية، أثرت في حياة الملايين منذ نشرها في عام 1922.\n\n«سدهارتا» هي قصة شاب يبحث عن الحقيقة المطلقة ويقابل بوذا، ويأخذه سعيه من حياة الانحلال إلى الزهد، ومن الشهوة والثروة والشهرة إلى الحكمة والتخلي.\n\nأهم وأجمل رواية لهرمان هسه، الحاصل على جائزة نوبل في الأدب، بترجمة سمير جريس الأمينة والجميلة", "/images/products/9789778678338.webp", "9789778678338", "سدهارتا", 224, 180m, new DateTime(2023, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 122, "سكوت فيتزجيرالد", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تربَّع هذا الكتاب لعدة سنوات على قائمة الكتب الأكثر مبيعًا\n\nأفضل ترجمة لهذه الرواية المهمة\n\nفي قصر فخم في نيويورك، في العشرينيات من القرن الماضي، يعيش المليونير الغامض «جاي جاتسبي» في الترف والرفاهة، ويقيم حفلات أسطورية باذخة يتهافت إليها المدعوون والمتطفلون. ولكن في قلب هذا الصخب، يبقى المضيف وحيدًا، تواقًا إلى حبه الضائع، غير معني إلا بإبهار شخص واحد: «ديزي بوكانان».\n\nرواية اجتماعية مذهلة، تجسد الحلم الأمريكي في «العشرينيات الذهبية»، بلمعانه المفرط وإخفاقه المحتوم، مسلطة الضوء على الصراع بين ا", "/images/products/9789776467491.webp", "9789776467491", "جاتسبي العظيم", 288, 245m, new DateTime(2017, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12.9×19.8", 10, false },
                    { 123, "ستانيسواف لَمْ", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أهم روايات الخيال العلمي وأكثرها مبيعًا\nهذه الرواية الفلسفية الممتعة، والتي تُعَد من كلاسيكيات أدب الخيال العلمي، تدور حول العالِم «كريس كلفين» الذي يصل إلى محطة فضائية قرب كوكب «سولاريس» لدراسة المحيط الذي يغطي سطحه، فيضطر لمواجهة ذكرى مؤلمة تتجسد في شبيهة لحبيبته التي ماتت منذ زمن طويل. يعاني علماء آخرون في المحطة من العلة نفسها، وتزداد التكهنات بأن محيط «سولاريس» قد يكون عقلًا ضخمًا يخلق ذكريات مجسدة، لكن غرضه من القيام بذلك يظل لغزًا.\nتطرح «سولاريس» سؤالًا شغل الإنسان منذ قرون: هل يمكننا حقًّا فهم الكون من حولنا من دون أن نفهم أولًا ما يكمن في داخلنا؟\nتُرجمت «سولاريس» إلى أكثر من أربعين لغةً، واقتبست مرات عديدة للسينما والراديو والمسرح، ومن أشهرها الفيلم الذي أخرجه «أندريه تاركوفسكي»، وآخر من إخراج «ستيفن سودربرج» وبطولة «جورج كلوني».\nستانيسواف لَمْ (1921-2006) هو مؤلف الخيال العلمي الأكثر شهرة والأكثر ترجمة خارج اللغة الإنجليزية، حيث باعت كتبه أكثر من خمسة وأربعين مليون نسخة، ونال العديد من التكريمات والجوائز. تتميز كتاباته برؤيتها الفلسفية العميقة. ومن أشهر أعماله «سولاريس»، التي نقدِّمها للمرة الأولى - مترجمة من البولندية مباشرة - بترجمة متميزة ودقيقة للأديب والمترجم العراقي هاتف جنابي.\nمديح\n«رواية من الطراز الأول» - جريدة الجارديان\n«رواية تجعلك تعيد التفكير في طبيعة الذكاء نفسه» - الأديبة «آن ماكافري»\n«رواية رائعة» - المخرج «ستيفن سودربرج»", "/images/products/9789776743540.webp", "9789776743540", "سولاريس", 280, 220m, new DateTime(2021, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 124, "أنطوان دو سانت اكزوبيري", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أهم الكتب الكلاسيكية العالمية\n\nأكثر الكتب ترجمةً في تاريخ الأدب العالمي\n\nيحتوي على الرسوم الأصلية للمؤلف\n\nترجمة جديدة متميزة\n\nطبعة خاصة تصدر بمناسبة الذكرى الـ75 لوفاة المؤلف\n\nيتعرض طيار لحادث فيسقط مع طائرته في الصحراء، وفي الصباح يستيقظ على طفل جميل يطلب منه: «من فضلك، ارسم لي حَمَلًا!». وبعد هول المفاجأة، يُدرك الطيار أنه عندما يصعب فهم الأحداث فلا خيار يتبقى للمرء سوى الخضوع للحياة وألغازها، فيُخرج من جيبه ورقة وقلمًا... وهكذا تبدأ هذه الحكاية الفاتنة التي تدور حول ما هو مُهم حقًّا في الح", "/images/products/9789776467811.webp", "9789776467811", "الأمير الصغير", 112, 120m, new DateTime(2019, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "16×22", 10, false },
                    { 125, "مارغريت آتوود", 2, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "رؤية مخيفة للمجتمع وقد تحوّل جذريًّا بسبب ثورة سياسيّة دينيّة متشدّدة. لقد باتت “حكاية الجارية” واحدة من أوسع الروايات قراءة في العالم وأكثرها تعلّقًا بالحاضر وقضاياه المؤثّرة. “أوفرِد” هي جارية في “جمهورية جلعاد”، تخدم في منزل “الرئيس” الغامض وزوجته حادّة الطّباع. تخرج مرة واحدة يوميًّا إلى الأسواق، حيث استُبدلت الصّور بكلّ اللافتات المكتوبة، فالنساء في جلعاد تحرّم عليهن القراءة. يجب عليها أن تصلي من أجل أن يجعلها الرّئيس حاملًا، ففي زمنها انخفضت معدّلات الولادة حتى صار وجود الأطفال في البيوت أ", "/images/products/9789948352068.webp", "9789948352068", "حكاية الجارية", 408, 220m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), null, 10, false },
                    { 126, "دان براون", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر المؤلفين مبيعًا\nمن أكثر الكتب مبيعًا\nيعود كاتب روايات التشويق الأشهر في العالم، دان براون، بروايةٍ جديدة تبهر العقول وتحبس الأنفاس. إنه عمل آسر متّقد الإيقاع، تتشابك فيه الأحداث والأفكار بمهارةٍ لا يجيدها سواه، فيقدم تجربة قراءةٍ تجمع بين المتعة والدهشة والتأمل العميق.\nخلال رحلة برفقة العالِمة المَرموقة كاثرين سولومون- التي دُعيت لإلقاء محاضرة في براغ - يجد روبرت لانغدون نفسه في دوامةٍ تخرج عن السيطرة؛ حين تختفي كاثرين من غرفتهما في الفندق من دون أثر. بعيدًا عن وطنه، وخارج محيطه المُعتاد، يُضطر لانغدون إلى مواجهة قوًى مَجهولة لاستعادة المرأة التي يُحبها.\nلكن براغ مدينة موغلة في القِدَم، تزخر بالأساطير ويكتنفها الغموض. فعلى مدى ألفَي عام، تقاذفتها أمواج التاريخ، فتركت في حجارتها صدى ما مضى من أحداث وتقلبات. ولم يكن لانغدون يُدرك أن طيفًا من ماضي المدينة المُظلم يُراقبه من كثب. غير أنه يجد نفسه مُرغَمًا على الاستعانة بكل ما في جعبته من مَعارف غامِضة لفك رموز ذلك العالم من حوله، قبل أن تبتلعه هو الآخر دوامات الخداع والخيانة التي ابتلعت كاثرين.\nهكذا، يجد لانغدون نفسه في مدينة سرية تختبئ في وضح النهار، مدينةٍ احتفظت بأسرارها قرونًا طويلة، ولن تُفصِح عنها بسهولة.\nإنها ساحة مَعركة لم يشهد لها مثيلًا من قبل، سيتحتم عليه فيها أن يُقاتل؛ ليس من أجل حياته فحسب، بل من أجل مستقبل البشرية نفسها.\nفي رواية «سر الأسرار»، يرجع دان براون إلى عالم الرواية بعد طول غياب، مُعيدًا إلى الواجهة عالِم الرموز في جامعة هارفارد، روبرت لانغدون، في مغامرةٍ جديدة تقوده إلى قلب مُؤامرةٍ ستمتحن عبقريته حتى أقصى حدودها، وتُعرِّض كل ما يعتز به لخطر الضياع.", "/images/products/9786039233473.webp", "9786039233473", "سر الأسرار", 584, 490m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "17×24", 10, false },
                    { 127, "أنتوني هورويتز", 3, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تنسج هذه الرواية المثيرة لغز جريمة قتل كلاسيكية يليق بأجاثا كريستي بأسلوب عصري مبتكر.\nعندما حصلت المحررة سوزان رايلاند على مخطوطة أحدث روايات مؤلفها آلان كونواي، لم يكن لديها أي سبب للاعتقاد بأنها ستكون مختلفة كثيرًا عن أيٍّ من رواياته السابقة. أثبتت روايات آلان نجاحها الكبير، مما أجبر سوزان على تحمُّل سلوك آلان المزعج إذا أرادت الاحتفاظ بوظيفتها.\nأحدث روايات آلان تدور حول جريمة قتل في قصر بالريف الإنجليزي الهادئ. نعم، هناك جثث ومجموعة مثيرة من المشتبه فيهم، ولكن كلما قرأت سوزان أكثر أيقنت بوجود قصة أخرى مخبأة في صفحات المخطوطة: قصة غيرة مدمرة، وجشع لانهائي، وطموح لا يوقفه شيء، وقتل...\n«بدافع القتل» رواية بارعة وذكية ومشوقة بلا هوادة لأنتوني هورويتز، الكاتب الإنجليزي الذي باعت كتبه أكثر من 21 مليون نسخة حول العالم.\nمديح\n««بدافع القتل»، لغز مزدوج لمحبي الألغاز» - النيويورك تايمز", "/images/products/9789779603001.webp", "9789779603001", "بدافع القتل", 576, 390m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 128, "إكهارت تول", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "نحتاج إلى ترك عقلنا التحليلي، وذاته المولدة الزائفة، الأنا، خلفنا، إن نحن أردنا السفر إلى قوة الآن. ننتقل بسرعة، ومنذ الصفحة الأولى لهذا الكتاب الاستثنائي، إلى ارتفاعات أعلى بشكل ملحوظ، نتنفس فيها هواء أقل كثافة. ونتصل بأساس وجودنا الذي لا يوصف، «الحياة الأبدية الواحدة الدائمة الوجود خلف الأشكال المختلفة للحياة الخاضعة للولادة والموت». ورغم صعوبة الرحلة، يستخدم إكهارت تول لغة بسيطة، ونسقا سهلا من سؤال وجواب، لتوجيهنا.\n\n«قوة الآن» من الكتب النادرة التي تتمتع بالقوة لخلق التجربة للقراء، وقد أصبح ع", "/images/products/9789953978550.webp", "9789953978550", "قوة الآن", 224, 280m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 129, "ديفيد ر. هاوكينز", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "يشرح كتاب السماح بالرحيل آلية بسيطة وفعالة يمكن من خلالها التخلص من معوقات التنوير، والتحرر من السلبية، حيث كان الهدف الأساسي للمؤلف خلال عدة عقود من الممارسة النفسية السريرية هو إيجاد الوسائل الأكثر فعالية في تخفيف معاناة البشر بجميع أشكالها، وقد وُجدت الآلية الداخلية للتسليم لتكون ذات منفعة عملية عظيمة وقد تم شرحها في هذا الكتاب.\n\nلقد ركزت كتب الدكتور هاوكنز السابقة على حالات الوعي المتقدمة والتنوير، وخلال هذه السنوات، طلب آلاف الطلاب تقنية عملية يمكن من خلالها أن يزيلوا المعوقات الداخلية للسع", "/images/products/9789953978574.webp", "9789953978574", "السماح بالرحيل", 384, 200m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 130, "بسيل فان دير كولك", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر الكتب مبيعًا في علم النفس\nيُقدِّم بيسيل فان دير كولك، الباحث الرائد وأحد أبرز الخبراء في العالم في مجال الضغط العصبي الناتج عن الصدمة النفسية، نموذجًا جديدًا جسورًا للشفاء من الصدمات.\nالصدمة النفسية حقيقة من حقائق الحياة. أظهرت الدراسات أن واحدًا على الأقل من كل خمسة أشخاص يتعرض للتحرش، وواحدًا من كل أربعة ينشأ مع مدمنين، وزوجًا من كل ثلاثة أزواج يتورط في عنف جسدي. هذه الظروف تترك حتمًا آثارًا في العقول والعواطف، وفي الجسد أيضًا. ومع الأسف، كثيرًا ما يعكس المصابون بالصدمات النفسية ضغطهم العصبي على شركائهم وأطفالهم.\nأمضى د. فان دير كولك أكثر من ثلاثة عقود في العمل مع الناجين من الصدمات، ونجح من خلال هذا الكتاب في تغيير فهمنا للضغط العصبي الناجم عن الصدمة النفسية، وكشف عن كيفية إعادة الضغط العصبي لترتيب أسلاك الدماغ حرفيًّا - تحديدًا المناطق المخصصة للمتعة والتفاعل مع الآخرين والتحكم في النفس والثقة - وأوضح تأثير العلاجات المبتكرة، بما في ذلك الارتجاع العصبي والتأمل والصلاة واللعب واليوجا وغيرها من العلاجات، فضلًا عن تقديمه بدائل مجربة وناجحة للعقاقير والعلاج بالكلام، وطريقة التعافي واستعادة الحياة.\nمديح\n«واضح ورائع ويصعب التوقف عن قراءته، ومليء بدراسات الحالة المهمة... قدَّم هذا الكتاب مجموعة من أهم الإنجازات في مجال الصحة العقلية خلال الأعوام الثلاثين الماضية» - نورمان دويدج، مؤلف كتاب «الدماغ يغير نفسه»", "/images/products/9789778678321.webp", "9789778678321", "جسمك يتذكر كل شيء", 632, 500m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 131, "ليندزي س. جيبسون", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر الكتب مبيعًا في مجال علم النفس\nإذا نشأت مع والد غير ناضج عاطفيًّا أو غير متاح أو أناني، فقد تكون لديك مشاعر دائمة من الغضب أو الوحدة أو الخيانة أو الهجر، قد تتذكر طفولتك على أنها الوقت الذي لم تتم فيه تلبية احتياجاتك العاطفية، أو تم فيه تجاهل مشاعرك، أو توليت فيه مسؤولية أكبر من سنك في محاولة للتعويض عن سلوك والديك. يمكن أن تلتئم هذه الجروح، ويمكنك المُضي قُدمًا في حياتك.\nفي هذا الكتاب الرائع، تكشف عالمة النفس السريري ليندزي س. جيبسون الطبيعة المدمرة للآباء غير الناضجين عاطفيًّا أو الآباء غير المتاحين. سترى كيف يخلق هؤلاء الآباء شعورًا بالإهمال، وتكتشف طرقًا للشفاء من الألم والارتباك اللذين سبَّبتهما طفولتك. من خلال تحرير نفسك من عدم النضج العاطفي لوالديك، يمكنك استعادة طبيعتك الأصلية، والتحكم في طريقة تفاعلك معهما، وتجنب خيبة الأمل. وأخيرًا، ستتعلم كيفية إنشاء علاقات إيجابية وجديدة حتى تتمكن من بناء حياة أفضل.", "/images/products/9789778721980.webp", "9789778721980", "أبناء بالغون لوالدين غير ناضجين عاطفيا", 272, 175m, new DateTime(2024, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 132, "بيجال شاه", 6, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذا الدليل الاستثنائي، تُحدثنا المعالِجة النفسية بيجال شاه عن مفهوم «العلاج بالقراءة» أو «الببليوثيرابي»، وكيف يمكن للقراءة أن تكون شكلًا من أشكال العلاج، مقدمةً نصائح عملية مدروسة، وقوائم كتب منتقاة بعناية لكل مزاج وحالة نفسية.\nتأخذنا شاه في رحلة عبر تاريخ هذا الفن العلاجي، مبيِّنة كيف واسى الأدب العظيم أرواحًا أثقلها الفقد والألم والتعقيدات العاطفية. وتشاركنا قصصًا حقيقية لمسترشديها الذين وجدوا في الكتب عزاءً وسط المِحن.\nهذا الكتاب احتفاء كبير بسحر الكتب، وتذكير رقيق بقدرتها الفريدة على مواساتنا وإعادة تشكيل حياتنا. إنه دعوة صادقة إلى إعادة اكتشاف القراءة، ليس كمهرب من الواقع فحسب، بل كأحد أصدق أشكال العناية بالذات.\nمديح\n«كتاب مدهش بكل معنى الكلمة» - بيث كيمبتون، مؤلفة الكتاب الأكثر مبيعًا «وابي سابي: الحكمة اليابانية للعيش المثالي في حياة غير مثالية»\n«من أروع ما قرأت منذ سنوات! مكتوب بأسلوب ساحر زاخر بالرؤى العميقة، يكشف لك عن القوة الشافية للقصص، وكيف يمكن للقراءة أن تغيِّر حياتك» - سايمون ألكسندر أونج، مؤلف الكتاب الأكثر مبيعًا «تنشَّط»", "/images/products/9789779603605.webp", "9789779603605", "العلاج بالقراءة", 296, 280m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 133, "كال نيوبورت", 5, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "في هذا الكتاب الرائع يتحدى كال نيوبورت النصيحة الشائعة: «اتبع شغفك». فهو يرى أن هذه المقولة ليست مضللة فحسب - لأن معظم الناس لا يملكون شغفًا واضحًا سابقًا - بل قد تكون ضارة أيضًا، إذ تؤدي إلى القلق والتخبط المهني.\nبدلًا من ذلك، يستعرض نيوبورت كيف يصل الناس فعلًا إلى حب ما يفعلونه. ويكشف من خلال لقاءات مع مزارعين، ومستثمرين، وكُتَّاب سيناريو، ومبرمجين مستقلين، أن الطريق إلى العمل المُرضي يبدأ بإتقان شيء ذي قيمة، فالشغف لا يسبق النجاح، بل يتولد عنه.\nينسف نيوبورت فكرة أن توافُق الوظيفة مع الشغف هو مفتاح السعادة. الأهم هو كيف تؤدي عملك، لا ماهيته. وبأسلوب واضح ومقنع، يقدِّم خريطة طريق عملية لبناء مسيرة مهنية ملهمة.\nسيغيِّر هذا الكتاب نظرتك إلى العمل والسعادة، ويتيح لك صناعة حياة استثنائية.\nمديح\n«يجب على المحترفين الطموحين أن يطوروا ميزة تنافسية من خلال بناء مهارات قيِّمة. هذا الكتاب يقدِّم نصائح تستند إلى البحث والواقع - وليس إلى شعارات جوفاء - حول كيفية الاستثمار في ذاتك لتتميز وسط الزحام. إنه دليل مهم لبدء مسيرة مهنية استثنائية» - ريد هوفمان، المؤسس المشارك ورئيس مجلس إدارة لينكد إن\n«يقدِّم هذا الكتاب نصائح وأمثلة ستدفعك مباشرة نحو بناء المهارات المهمة حقًّا» - دانيال إتش. بينك، المؤلف الأكثر مبيعًا لكتاب «الحافز»\n«هذا الكتاب غيَّر قناعاتي. لقد نقلني من فكرة «ابحث عن شغفك لتكون مفيدًا» إلى «كن مفيدًا لتجد شغفك». إنها نقلة كبيرة، ولكنها أكثر صدقًا، ولهذا السبب أهديت نسخة من هذا الدليل غير التقليدي إلى كلٍّ من أولادي الثلاثة» - كيفن كيلي، كبير المحررين المبتكرين في مجلة «وايرد»\n«أول كتاب أقرأه مرتين منذ سنوات لأتأكد من استيعابه. رؤى مهنية لامعة ومخالفة للتوقعات. أفكار قوية وجديدة غيَّرت بالفعل طريقة تفكيري في مسيرتي المهنية، والنصائح التي أقدِّمها إلى الآخرين» - ديريك سيفرز، مؤسس شركة الموسيقى سي دي بيبي", "/images/products/9789779603612.webp", "9789779603612", "كن أروع من أن يتجاهلوك", 248, 200m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 134, "صلاح عيسى", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "طبعة جديدة فاخرة لأحد أكثر الكتب التاريخية مبيعًا\nأهم كتاب يتناول هذه العصابة الشهيرة\nالسيرة الوحيدة التي تستند إلى الوثائق والأرشيفات، مسرودة بأسلوب شيق وممتع\nيتضمن الكتاب صور فوتوغرافية كثيرة نادرة للشخصيات والأماكن والوقائع\nتحولت ريا وسكينة منذ القبض عليهما عام 1921 إلى أسطورة في الخيال الشعبي والجمعي للمصريين، وكنموذج مُخيف ومُرعب للشر المجرد. ولم يحاول أي من المؤرخين أو علماء الاجتماع طوال كل هذه الأعوام تقصي حقيقة هذه الجرائم، أو دراسة الدوافع وراء ارتكابها، حتى قدَّم لنا صلاح عيسى هذه السيرة الاجتماعية السياسية غير المسبوقة.\nويستند كاتبنا الكبير إلى الملفات القضائية، والوثائق التاريخية، والأرشيفات الصحفية، وعدد كبير من المراجع المعروفة وغير المعروفة ليرسم لنا - ولأول مرة - صورة حقيقية وحية عن هذه الشخصيات المثيرة وأوضاع مصر السياسية والاجتماعية والاقتصادية في ذلك العصر.\nوبالإضافة لأسلوب صلاح عيسى الشيق والممتع يمتلئ الكتاب أيضًا بعشرات الصور الفوتوغرافية للأشخاص والأماكن والوقائع؛ فيعطي المؤلف التاريخ حقه بإخلاصه للحقائق الموثقة، ويعطي القارئ حقه في الاستمتاع باكتشاف هذا التاريخ، وبمعايشة أجوائه وشخصياته.", "/images/products/9789776467248.webp", "9789776467248", "رجال ريا وسكينة", 528, 600m, new DateTime(2018, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "19.5×27.5", 10, false },
                    { 135, "محمد سلماوي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "تجمع هذه الحوارات القصيرة الممتعة خلاصة فكر أديبنا الأكبر نجيب محفوظ وهو في قمة نضجه وحكمته، فنتعرف على آرائه في الثقافة والسياسة والدين، وذكرياته، من خلال اللقاءات الأسبوعية الشهيرة التي كان يجريها معه الكاتب محمد سلماوي لتُنشر كل أسبوع في «الأهرام» لمدة 12 عامًا منذ عام 1994 وحتى وفاته عام 2006.\nويقول الكاتب الكبير محمد سلماوي في مقدمة هذا الكتاب: «في هذه الحوارات تتضح بصيرة نجيب محفوظ وموسوعية معرفته وشمول رؤيته مما يجعلها صالحة لكل العصور، حتى يكاد القارئ يشعر بأنها أجريت اليوم، وأن محفوظ يتحدث فيها عن موضوعات حالية، ويطرح آراء ما أحوجنا إليها فيما نواجهه اليوم من مشاكل... لكنها قبل كل ذلك وبعده، جلسة حميمية تأخذ القارئ إلى مجلس رجل من أعظم وأمتع رجالات مصر في عصرنا الحديث».", "/images/products/9789779603131.webp", "9789779603131", "حوارات نجيب محفوظ", 320, 300m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14.5×21.5", 10, false },
                    { 136, "طه حسين", 7, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر الكتب مبيعًا\n\nطبعة مدققة ومراجعة بدون أخطاء\n\nطبعة جيب أنيقة وجذابة\n\nيقول عميد الأدب العربي في الجزء الأول من سيرته الخلابة والتي تعتبر من أجمل السير الذاتية العربية: «لست أدري لماذا رجعت ذات يوم إلى ذكريات الصبا، أتحدث بها إلى نفسي لأنسى بهذا الحديث أثقال الشباب. ثم لم أكتفِ بالتحدث إلى نفسي فيما بيني وبينها، وإنما تحدثت إليها حديثًا مسموعًا، فأمليت هذا الكلام على صاحبي في رحلة من رحلات الصيف، ثم ألقيته جانبًا ونسيته أو كدت أنساه»\n\nالجزء الأول\n\nالسلسلة: المكتبة التراثية الصغيرة\n\n«المكتبة", "/images/products/9789779603216.webp", "9789779603216", "الأيام", 136, 105m, new DateTime(2025, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12×17", 10, false },
                    { 137, "غسان كنفاني", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر الكتب مبيعًا\n\nمدققة ومراجعة بدون أخطاء\n\nطبعة جيب أنيقة وجذابة\n\n«رجال في الشمس» رواية تزلزل الضمير، وتطرح سؤالًا لا يزال يلاحق كل من عايش النكبة: «لماذا لم يدقوا جدران الخزان؟!».\n\nثلاثة رجال فلسطينيين، من أجيال مختلفة، يسعون لعبور الحدود نحو حلم هش بالكرامة والعمل، لكن الطريق إلى الكويت ليس مجرد رحلة جغرافية، بل اختبار قاسٍ للإنسانية، وتجسيد لمعنى الخذلان، ومؤشر على الصمت الذي يقتل أكثر من الرصاص.\n\nبأسلوبه المكثف والموجع، يكشف غسان كنفاني عن مأساة شعب لم يُهزم بالاحتلال فحسب، بل أيضًا بال", "/images/products/9789779603735.webp", "9789779603735", "رجال في الشمس", 128, 70m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12×17", 10, false },
                    { 138, "غسان كنفاني", 1, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر الكتب مبيعًا\n\nمدققة ومراجعة بدون أخطاء\n\nطبعة جيب أنيقة وجذابة\n\n«عائد إلى حيفا» ليست مجرد رواية، بل مواجهة مؤلمة مع سؤال الهوية، والانتماء، والذاكرة التي لا تموت.\n\nفي رحلة العودة إلى المدينة التي سُلبت، يفتح غسان كنفاني جرحًا فلسطينيًّا لم يندمل. زوجان يعودان إلى حيفا بعد عشرين عامًا من النكبة، ليبحثا عن ابنهما الذي تركاه خلفهما في لحظة الهروب، لكن ما ينتظرهما هناك ليس الحقيقة فحسب، بل اختبار قاسٍ لمعنى الوطن، والخسارة، والاختيار.\n\nبأسلوبه الحاد والعاطفي، يكتب كنفاني نصًّا يتجاوز الرواية", "/images/products/9789779603711.webp", "9789779603711", "عائد إلى حيفا", 96, 60m, new DateTime(2026, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12×17", 10, false },
                    { 139, "صون تزو", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "أحد أكثر الكتاب مبيعًا في العالم في طبعة مصرية محققة\n\nلقد استطاع \"سون تزو\" أنْ يؤكّد من خلال كتابه: \"فنُّ الحرب\" – وهو الكتاب الذي كان يُعدّ الكتاب المقدّس في الدراسات العسكريَّة - بـأنَّ من الأمور المستحيلة؛ هي التكهّن مُسبقاً بمصير المعركة، وتوقّع ما قد يتخلّلها من أحداث؛ أو ما قد يظهر فيها من مفاجآت؛ وهذا يدعو القائد بالضرورة إلى اعتماد استراتيجيَّات وخطط حربيَّة مرنة. ولذا؛ فقد استطاع \"تزو\" أنْ يقنع جنوده بأنَّ الحرب فكرٌ وفنٌّ؛ وليست قتال ودماء.\n\nكان \"سون تزو\" يؤمن بأنَّ القائد المثالي الذي", "/images/products/9789779603544.webp", "9789779603544", "فن الحرب", 88, 60m, new DateTime(2020, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "14×21", 10, false },
                    { 140, "نيقولا ماكيافيلي", 8, new DateTime(2026, 10, 29, 0, 0, 0, 0, DateTimeKind.Utc), "من أكثر الكتب مبيعًا\n\nطبعة جيب أنيقة وجذابة\n\nاتهم الناس ماكيافيلي بأنه سنَّ في كتابه أقسى أساليب الاستغلال وأفظعها، وابتدع أظلم خطة للتحكم في الأعناق. لكن الحقيقة أن ماكيافيلي قضى عمره في خدمة أهل وطنه، والسعي في تأسيس بناء العدل ليعيشوا في ظله، وقد جلب عليه تطرفه للعدل والحق فقدان منصبه في جمهورية فلورنسا.\n\nكتب ماكيافيلي ما كتب ليدل الناس على مواطن الغدر، وليفطنوا إلى صنوف الخداع فيما يُدبَّر ضدهم، وما يُدَس لهم من الدسائس، ولو أن الناس تدبروا كتابه لما تمكن أحد من إيذائهم.\n\nلقد آنَ للقارئ أن ي", "/images/products/9789776743717.webp", "9789776743717", "الأمير", 240, 110m, new DateTime(2022, 1, 1, 0, 0, 0, 0, DateTimeKind.Utc), "12×17", 10, false }
                });
        }

